            <section class="surface overflow-hidden"><div class="flex flex-wrap items-center justify-between gap-3 border-b border-zinc-200 p-5 dark:border-white/10"><h3 class="font-semibold">{{ $weekDays->first()->format('M j') }} – {{ $weekDays->last()->format('M j, Y') }}</h3><div class="flex flex-wrap items-center justify-end gap-3"><flux:select wire:model.live="timeGroup" class="w-40" aria-label="Group time tracker"><flux:select.option value="none">No grouping</flux:select.option><flux:select.option value="project">By project</flux:select.option><flux:select.option value="customer">By customer</flux:select.option></flux:select><div class="flex"><flux:button wire:click="changeWeek(-1)" :loading="false" variant="ghost" icon="chevron-left" /><flux:button wire:click="$set('weekStart','{{ now()->startOfWeek()->toDateString() }}')" variant="ghost">Today</flux:button><flux:button wire:click="changeWeek(1)" :loading="false" variant="ghost" icon="chevron-right" /></div></div></div><div class="overflow-x-auto"><div class="min-w-[980px]"><div class="grid grid-cols-[minmax(220px,1.5fr)_repeat(7,minmax(96px,1fr))]"> <div class="p-4 text-xs font-semibold uppercase text-zinc-500">Bookmarked tickets</div>@foreach($weekDays as $day)<div class="border-l p-3 text-center text-xs dark:border-white/10 {{ $day->isWeekend()?'bg-zinc-100 dark:bg-black/30':'' }}"><b class="block">{{ $day->format('D') }}</b><span class="timesheet-date relative mt-0.5 block">{{ $day->format('j M') }}</span></div>@endforeach</div>@forelse($timeTicketGroups as $timeGroupLabel => $groupedTimeTickets)@if($timeGroup !== 'none')<div class="border-t border-zinc-200 bg-zinc-50 px-4 py-2 text-xs font-semibold uppercase tracking-wide text-zinc-500 dark:border-white/10 dark:bg-white/5">{{ $timeGroupLabel }}</div>@endif @foreach($groupedTimeTickets as $ticket)<div class="grid grid-cols-[minmax(220px,1.5fr)_repeat(7,minmax(96px,1fr))] border-t border-zinc-100 dark:border-white/10"><div class="flex min-w-0 items-center gap-2 px-2 py-3"><button wire:click.stop="toggleTicketBookmark({{ $ticket->id }})" class="shrink-0 rounded-md p-1 {{ $ticket->time_bookmarked?'text-falqo-600':'text-zinc-400' }}" aria-label="{{ $ticket->time_bookmarked?'Remove bookmark':'Bookmark for time' }}" title="{{ $ticket->time_bookmarked?'Remove bookmark':'Bookmark for time' }}"><x-lucide-icon name="bookmark" :filled="$ticket->time_bookmarked" class="size-5" /></button><p class="flex min-w-0 items-center gap-2 truncate text-sm font-medium"><x-lucide-icon :name="$ticket->category->icon()" class="size-4 shrink-0 text-zinc-500" /><span class="truncate">#{{ $ticket->id }} {{ $ticket->title }}</span></p></div>@foreach($weekDays as $day)@php($m=$weekEntries->where('ticket_id',$ticket->id)->filter(fn($e)=>$e->started_at->isSameDay($day))->sum->minutes)<button wire:click="openTimeEntry({{ $ticket->id }},'{{ $day->toDateString() }}')" class="time-entry-cell group relative flex items-center justify-center border-l p-2 text-sm dark:border-white/10 {{ $day->isWeekend()?'bg-zinc-100 dark:bg-black/30':'' }}">@if($m)<span>{{ intdiv($m,60) }}h {{ $m%60 }}m</span><span class="pointer-events-none absolute inset-0 flex items-center justify-center"><span class="inline-flex size-9 origin-center scale-0 items-center justify-center rounded-full bg-falqo-600/80 text-white opacity-0 shadow-sm backdrop-blur-[1px] transition-all duration-200 ease-out group-hover:scale-100 group-hover:opacity-100"><x-lucide-icon name="plus" class="size-5" /></span></span>@else<span class="inline-flex size-9 items-center justify-center"><span class="inline-flex size-6 items-center justify-center rounded-full text-zinc-400 transition-all duration-200 ease-out group-hover:size-9 group-hover:bg-falqo-600/80 group-hover:text-white"><x-lucide-icon name="plus" class="size-3.5 transition-all duration-200 group-hover:size-5" /></span></span>@endif</button>@endforeach</div>@endforeach @empty<div class="p-8 text-center text-sm text-zinc-500">Bookmark tickets assigned to you to show them here.</div>@endforelse<div class="grid grid-cols-[minmax(220px,1.5fr)_repeat(7,minmax(96px,1fr))] bg-zinc-50 font-semibold dark:bg-white/5"><div class="p-4">Total</div>@foreach($weekDays as $day)@php($m=$weekEntries->filter(fn($e)=>$e->started_at->isSameDay($day))->sum->minutes)<div wire:key="timesheet-total-{{ $day->toDateString() }}" x-data="{ hours: 0, minutes: 0, targetHours: {{ intdiv($m,60) }}, targetMinutes: {{ $m%60 }} }" x-init="let started; const tick = now => { started ??= now; const progress = Math.min((now - started) / 1200, 1); hours = Math.round(targetHours * progress); minutes = Math.round(targetMinutes * progress); if (progress < 1) requestAnimationFrame(tick) }; requestAnimationFrame(tick)" class="border-l p-4 text-center font-mono text-sm dark:border-white/10 {{ $day->isWeekend()?'bg-zinc-200 dark:bg-black/30':'' }}"><span wire:loading.remove wire:target="changeWeek,weekStart"><span x-text="hours"></span>h <span x-text="minutes"></span>m</span><span wire:loading wire:target="changeWeek,weekStart">0h 0m</span></div>@endforeach</div></div></div></section>
